import anthropic
client = anthropic.Anthropic()

tools = [{
    "name": "get_weather",
    "description": "Get the current weather for a city. Use when the user asks about current conditions. Returns temperature and conditions only.",
    "input_schema": {
        "type": "object",
        "properties": {"location": {"type": "string", "description": "City and state, e.g. San Francisco, CA"}},
        "required": ["location"],
    },
}]

messages = [{"role": "user", "content": "What's the weather in Paris?"}]
MAX_TURNS = 10

for _ in range(MAX_TURNS):
    response = client.messages.create(
        model="claude-sonnet-5-5", max_tokens=1024, tools=tools, messages=messages
    )
    if response.stop_reason != "tool_use":
        break
    messages.append({"role": "assistant", "content": response.content})
    results = []
    for block in response.content:
        if block.type == "tool_use":
            try:
                out = run_tool(block.name, block.input)   # your code
                results.append({"type": "tool_result", "tool_use_id": block.id, "content": out})
            except Exception as e:
                results.append({"type": "tool_result", "tool_use_id": block.id,
                                "content": f"Error: {e}. Check the city name and retry.", "is_error": True})
    messages.append({"role": "user", "content": results})   # results only, no text first

{
  "name": "get_weather",
  "description": "Get the current weather in a given location. Returns temperature and conditions. Does not return forecasts.",
  "input_schema": {
    "type": "object",
    "properties": {
      "location": {"type": "string", "description": "The city and state, e.g. San Francisco, CA"},
      "unit": {"type": "string", "enum": ["celsius", "fahrenheit"]}
    },
    "required": ["location"]
  },
  "input_examples": [
    {"location": "San Francisco, CA", "unit": "fahrenheit"},
    {"location": "New York, NY"}
  ]
}

import asyncio
from claude_agent_sdk import query, ClaudeAgentOptions, ResultMessage

async def run():
    try:
        async for message in query(
            prompt="Find and fix the bug causing test failures in the auth module",
            options=ClaudeAgentOptions(
                allowed_tools=["Read", "Edit", "Bash", "Glob", "Grep"],
                setting_sources=["project"],   # load CLAUDE.md, skills, hooks
                max_turns=30,
                max_budget_usd=2.0,
                effort="high",
            ),
        ):
            if isinstance(message, ResultMessage):
                if message.subtype == "success":
                    print(message.result)
                elif message.subtype == "error_max_turns":
                    print("Out of turns; resume session", message.session_id)
                elif message.subtype == "error_max_budget_usd":
                    print("Budget hit")
                print("cost", message.total_cost_usd)
    except Exception as e:
        print("Session ended with an error:", e)

asyncio.run(run())

import { tool, createSdkMcpServer, query } from "@anthropic-ai/claude-agent-sdk";
import { z } from "zod";

const fetchData = tool(
  "fetch_data",
  "Fetch JSON from an API endpoint. Returns the response body as text.",
  { endpoint: z.string().url().describe("API endpoint URL") },
  async (args) => {
    try {
      const res = await fetch(args.endpoint);
      if (!res.ok) {
        return { content: [{ type: "text", text: `API error: ${res.status}` }], isError: true };
      }
      return { content: [{ type: "text", text: JSON.stringify(await res.json()) }] };
    } catch (e) {
      return { content: [{ type: "text", text: `Failed to fetch: ${e}` }], isError: true };
    }
  },
  { annotations: { readOnlyHint: true } }
);

const server = createSdkMcpServer({ name: "api", version: "1.0.0", tools: [fetchData] });

for await (const m of query({
  prompt: "Get https://example.com/api/status",
  options: { mcpServers: { api: server }, allowedTools: ["mcp__api__fetch_data"] },
})) { /* handle messages */ }

