async def protect_env_files(input_data, tool_use_id, context):
    file_path = input_data["tool_input"].get("file_path", "")
    if file_path.split("/")[-1].lower() == ".env":
        return {
            "hookSpecificOutput": {
                "hookEventName": input_data["hook_event_name"],
                "permissionDecision": "deny",
                "permissionDecisionReason": "Cannot modify .env files",
            }
        }
    return {}

options = ClaudeAgentOptions(
    hooks={"PreToolUse": [HookMatcher(matcher="Write|Edit", hooks=[protect_env_files])]}
)

for await (const message of query({
  prompt: "Audit every service for unhandled promise rejections",
  options: {
    allowedTools: ["Read", "Grep", "Glob", "Agent"],
    env: {
      ...process.env,                                  // TS replaces the env
      CLAUDE_CODE_MAX_SUBAGENT_SPAWN_DEPTH: "1",       // no nested subagents
      CLAUDE_CODE_MAX_CONCURRENT_SUBAGENTS: "5",
    },
    maxTurns: 40,
    maxBudgetUsd: 5,
  },
})) {
  if (message.type === "result") console.log(message.subtype, message.total_cost_usd);
}
